"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { ButtonGroup } from "@/components/ui/button-group"
import { cn } from "@/lib/utils"
import type { Column } from "@/lib/configure-report-data"

import { RemoveColumnIcon } from "./icons"

/**
 * Drawn in the gap beside a chip, on whichever side the chip would land.
 *
 * Spelled out per side because a variant has to prefix every class it covers —
 * `cn("before:-start-1", SHARED)` leaves the rest unprefixed and styles the
 * chip itself, which collapses it to a 2px sliver and reflows the row.
 */
const DROP_LINE_BEFORE =
  "before:absolute before:top-0 before:-start-1 before:h-full before:w-0.5 before:rounded-full before:bg-primary before:content-['']"

const DROP_LINE_AFTER =
  "after:absolute after:top-0 after:-end-1 after:h-full after:w-0.5 after:rounded-full after:bg-primary after:content-['']"

/** Two chips belong to the same visual row if their tops agree to the pixel. */
const SAME_ROW = 4

type Landing = {
  /** Where the chip goes, counted between chips. */
  at: number
  /** Which chip the line is drawn against, and on which side of it. */
  chip: number
  side: "before" | "after"
}

/**
 * Work out where a chip would land from the pointer, across wrapped rows.
 *
 * Comparing x alone is only right while every chip is on one line. Once the
 * list wraps, the chip nearest in x can be a row away, so the pointer's row is
 * picked first and the position within it second — which is also what makes
 * the end of one row and the start of the next tell themselves apart when they
 * are the same insertion index.
 */
function landingFor(x: number, y: number, boxes: DOMRect[]): Landing | null {
  if (boxes.length === 0) return null

  const rows: number[][] = []
  boxes.forEach((box, index) => {
    const row = rows.find(
      (indexes) => Math.abs(boxes[indexes[0]].top - box.top) < SAME_ROW,
    )
    if (row) row.push(index)
    else rows.push([index])
  })

  /* The row the pointer is inside, or the closest one when it is in the gap
     between rows or below the last of them. */
  let chosen = rows[0]
  let nearest = Number.POSITIVE_INFINITY
  for (const row of rows) {
    const box = boxes[row[0]]
    const distance =
      y < box.top ? box.top - y : y > box.bottom ? y - box.bottom : 0
    if (distance < nearest) {
      nearest = distance
      chosen = row
    }
  }

  for (const index of chosen) {
    const box = boxes[index]
    if (x < box.left + box.width / 2) {
      return { at: index, chip: index, side: "before" }
    }
  }

  /* Past the last chip on this row — the line belongs on its trailing edge,
     not at the start of the row below. */
  const last = chosen[chosen.length - 1]
  return { at: last + 1, chip: last, side: "after" }
}

/**
 * A set of columns as chips, in the order they will appear in the export.
 *
 * Each chip is two buttons in a ButtonGroup rather than one: the label is the
 * grab handle and the × is the only thing that removes. One button doing both
 * meant every attempt to pick a chip up deleted it — and the order is the
 * point here, since these are spreadsheet columns left to right.
 *
 * The drop line is a pseudo-element, not a real element spliced into the row.
 * A real one is 2px plus two gaps wide, so showing it reflowed every chip
 * after it, which slid a different chip under the pointer, which moved the
 * line again — the drag shook.
 *
 * Both dragover and drop are handled once on the wrapper rather than per chip.
 * The wrapper covers the gaps between chips and the space past the end of a
 * row, which a chip's own handler never sees, and one listener cannot fire
 * twice for one drop.
 */
export function ColumnChips({
  columns,
  onRemove,
  onReorder,
}: {
  columns: Column[]
  onRemove: (id: string) => void
  onReorder: (from: number, to: number) => void
}) {
  const [dragging, setDragging] = React.useState<number | null>(null)
  const [landing, setLanding] = React.useState<Landing | null>(null)

  /* The same value as `dragging`, kept where the handlers can read it without
     waiting for a render. A dragover that arrives in the same tick as the
     dragstart still sees state as null, and the first move of a drag is
     exactly when that happens — so the drag would ignore its own opening
     gesture. The state copy is only for the dimming. */
  const draggingRef = React.useRef<number | null>(null)
  /* Same reason: a drop can follow its last dragover inside one frame, and
     reading the landing from state there would drop the chip nowhere. */
  const landingRef = React.useRef<Landing | null>(null)

  function move(from: number, to: number) {
    if (to < 0 || to >= columns.length || from === to) return
    onReorder(from, to)
  }

  function end() {
    draggingRef.current = null
    landingRef.current = null
    setDragging(null)
    setLanding(null)
  }

  return (
    <div
      className="flex flex-wrap items-stretch gap-2"
      onDragOver={(event) => {
        /* Without preventDefault the browser refuses the drop. */
        event.preventDefault()
        if (draggingRef.current === null) return

        const boxes = [
          ...event.currentTarget.querySelectorAll<HTMLElement>(
            ':scope > [data-slot="button-group"]',
          ),
        ].map((chip) => chip.getBoundingClientRect())

        const next = landingFor(event.clientX, event.clientY, boxes)
        landingRef.current = next

        setLanding((current) =>
          current &&
          next &&
          current.at === next.at &&
          current.chip === next.chip &&
          current.side === next.side
            ? current
            : next,
        )
      }}
      onDragLeave={(event) => {
        /* Only when the pointer actually leaves the group, not when it crosses
           between two chips inside it. */
        if (!event.currentTarget.contains(event.relatedTarget as Node)) {
          landingRef.current = null
          setLanding(null)
        }
      }}
      onDrop={(event) => {
        event.preventDefault()
        const from = draggingRef.current
        const to = landingRef.current
        if (from !== null && to !== null) {
          /* Removing the chip first shifts everything after it down one, so a
             landing slot past the chip's own position is one place too far. */
          move(from, to.at > from ? to.at - 1 : to.at)
        }
        end()
      }}
    >
      {columns.map((column, index) => {
        /* Both sides of the dragged chip put it back where it started, so
           neither gets a line — an indicator promising nothing is just one
           more thing flickering. */
        const noop =
          dragging !== null &&
          landing !== null &&
          (landing.at === dragging || landing.at === dragging + 1)
        const live = dragging !== null && landing !== null && !noop

        return (
          <ButtonGroup
            className={cn(
              "relative transition-opacity duration-150 ease-out-cubic select-none motion-reduce:transition-none",
              dragging === index && "opacity-50",
              live &&
                landing.chip === index &&
                landing.side === "before" &&
                DROP_LINE_BEFORE,
              live &&
                landing.chip === index &&
                landing.side === "after" &&
                DROP_LINE_AFTER,
            )}
            draggable
            key={column.id}
            onDragEnd={end}
            onDragStart={() => {
              draggingRef.current = index
              setDragging(index)
            }}
          >
            <Button
              className="cursor-grab active:cursor-grabbing"
              onKeyDown={(event) => {
                if (event.key !== "ArrowLeft" && event.key !== "ArrowRight")
                  return
                event.preventDefault()
                move(index, index + (event.key === "ArrowLeft" ? -1 : 1))
              }}
              size="xs"
              title="Drag, or press the arrow keys, to reorder"
              type="button"
              variant="outline"
            >
              {column.label}
            </Button>

            <Button
              aria-label={`Remove ${column.label}`}
              onClick={() => onRemove(column.id)}
              size="icon-xs"
              type="button"
              variant="outline"
            >
              <RemoveColumnIcon />
            </Button>
          </ButtonGroup>
        )
      })}
    </div>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Command,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import { Label } from "@/components/ui/label"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import type { Column } from "@/lib/configure-report-data"

import { AddColumnIcon } from "./icons"

/**
 * Picks every column in one group at once.
 *
 * Checkboxes rather than a menu that adds one row and shuts: a report is
 * usually built by taking most of a group, and doing that a click and a reopen
 * at a time is the thing reviewers keep asking us to stop making them do. The
 * list stays open, ticking is instant, and "Select all" takes the whole group
 * — or, once a search is typed, just what the search matched.
 *
 * Every option is shown, with the ones already on the report ticked, so the
 * list reads as the group's state rather than as a pile of leftovers. That
 * makes unticking a removal, which is the same edit the chip's × makes.
 *
 * Search is filtered here rather than by cmdk, because "Select all" has to
 * know exactly which rows are on screen to act on them.
 */
export function ColumnPicker({
  emptyLabel,
  onChange,
  options,
  placeholder,
  selected,
}: {
  emptyLabel: string
  onChange: (columns: Column[]) => void
  options: Column[]
  placeholder: string
  selected: Column[]
}) {
  const [open, setOpen] = React.useState(false)
  const [query, setQuery] = React.useState("")
  const selectAllId = React.useId()

  const on = new Set(selected.map((column) => column.id))

  const needle = query.trim().toLowerCase()
  const visible = needle
    ? options.filter((option) => option.label.toLowerCase().includes(needle))
    : options

  const allVisibleOn = visible.length > 0 && visible.every((o) => on.has(o.id))

  /**
   * Whatever was already on keeps its place — these are spreadsheet columns,
   * and reordering them behind the reader's back is worse than any tidiness
   * gained. Newly ticked ones land at the end, in the order this list has
   * them, so a "Select all" produces the group top to bottom.
   */
  function apply(next: Set<string>) {
    const kept = selected.filter((column) => next.has(column.id))
    const added = options.filter(
      (option) => next.has(option.id) && !on.has(option.id),
    )
    onChange([...kept, ...added])
  }

  function toggle(option: Column) {
    const next = new Set(on)
    if (next.has(option.id)) next.delete(option.id)
    else next.add(option.id)
    apply(next)
  }

  function toggleVisible() {
    const next = new Set(on)
    for (const option of visible) {
      if (allVisibleOn) next.delete(option.id)
      else next.add(option.id)
    }
    apply(next)
  }

  return (
    <Popover
      onOpenChange={(next) => {
        setOpen(next)
        /* A search left behind from last time reads as an empty group. */
        if (!next) setQuery("")
      }}
      open={open}
    >
      <PopoverTrigger asChild>
        <Button variant="outline">
          Add
          <AddColumnIcon data-icon="inline-end" />
        </Button>
      </PopoverTrigger>

      <PopoverContent align="end" className="w-80 p-0">
        <Command shouldFilter={false}>
          <CommandInput
            onValueChange={setQuery}
            placeholder={placeholder}
            value={query}
          />

          {/* Outside the list, so it cannot scroll away from the rows it
              acts on.

              PADDED ON BOTH SIDES, which it was not: the air above it was a
              margin and the air below it was padding, so the row's own box
              started at the label and the divider sat 12px under it with
              nothing above. The label read as a caption hanging off the search
              field rather than as the head of the list, and the row measured
              29px against the 32px of every option beneath it — a header
              shorter than its own contents.

              `py-2.5` gives the label equal air on both sides and makes the row
              the tallest thing in the list, which is what a header should be.
              The remaining `mt-1` is separation from the input above, not part
              of the row. */}
          {/* The whole row is the label, not just its words. As a bare box
              beside a checkbox it was the one row in the popover that did not
              light up under the pointer and did not answer a click off the
              text — so it read as a caption, and people aimed at the 16px
              checkbox. Same inset and the same `bg-muted` fill the options
              use, so it behaves like the list it heads. */}
          {/* `pb-1` matches the `mt-1` above, so the row's hover fill has the
              same 4px of clearance top and bottom. Without it the fill's
              rounded bottom corners land on the divider and the two read as
              one smudged edge. */}
          <div className="mx-1 mt-1 border-b pb-1">
            <Label
              className="rounded-sm px-2 py-2.5 hover:bg-muted"
              htmlFor={selectAllId}
            >
              <Checkbox
                checked={allVisibleOn}
                disabled={visible.length === 0}
                id={selectAllId}
                onCheckedChange={toggleVisible}
              />
              {/* Named for exactly what it will touch. Once a search is typed
                  this row acts on the matches only, and a bare "Clear" beside
                  two visible rows reads as if it empties the whole group. */}
              {needle
                ? `${allVisibleOn ? "Clear" : "Select"} ${visible.length} ${
                    visible.length === 1 ? "match" : "matches"
                  }`
                : allVisibleOn
                  ? "Clear all"
                  : "Select all"}
              <span className="ms-auto text-xs font-normal text-muted-foreground">
                {selected.length} of {options.length} on
              </span>
            </Label>
          </div>

          {/* Only the top. The rows carry their own hover fill and need
              clearing from the divider, but the frame's own padding already
              gives the last one 8px — pad both ends and the bottom comes out
              at 12 against the top's 8, which reads as a slipped margin. */}
          <CommandList className="pt-1">
            {visible.length === 0 ? (
              <p className="py-6 text-center text-sm text-muted-foreground">
                {emptyLabel}
              </p>
            ) : (
              <CommandGroup>
                {visible.map((option) => (
                  <CommandItem
                    key={option.id}
                    onSelect={() => toggle(option)}
                    value={option.id}
                  >
                    {/* The row is the hit target — a checkbox that also took
                        clicks would swallow half of them and toggle twice. */}
                    <Checkbox
                      checked={on.has(option.id)}
                      className="pointer-events-none"
                      tabIndex={-1}
                    />
                    {option.label}
                  </CommandItem>
                ))}
              </CommandGroup>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

import {
  AlertCircleIcon,
  Cancel01Icon,
  PlusSignIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/icon"

/** Takes one column back out of the export. */
export const RemoveColumnIcon = icon(Cancel01Icon, "RemoveColumnIcon")

/** Opens a group's column picker. */
export const AddColumnIcon = icon(PlusSignIcon, "AddColumnIcon")

/** Marks the note about the export running in the background. */
export const BackgroundTaskIcon = icon(AlertCircleIcon, "BackgroundTaskIcon")

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
